  "settings.compressionInfo": "Как restic пакетира новите данни в това хранилище. Автоматично е стандартът на restic и пасва на повечето данни. Максимално пести повече място и струва повече процесорно време при архивиране и копиране. Изключено записва данните без компресия, което помага, когато те вече са компресирани, например видео или снимки. Хранилище в стария формат версия 1 не може да компресира и пренебрегва тази настройка.",
