  "dest.token.tip": "BombVault работи на сървър без браузър. rclone отваря входа на твоя компютър и после отпечатва токен, който се въвежда в полето по-долу. rclone за Windows, macOS и Linux има на rclone.org.",
  "dest.sshKey": "Добави публичния SSH ключ на BombVault към сървъра",
  "dest.sshKey.tip": "Същият ключ, който BombVault използва за архиви на виртуални машини през SSH. С поставен ключ не е нужна парола, а входът с парола може да се изключи на сървъра.",
  "dest.appPassword.tip": "При включена двуфакторна автентикация обикновената парола не работи. Създай парола за приложение в настройките за сигурност на акаунта си.",
  "dest.key.note": "Ключовете се съхраняват криптирани заедно с другите облачни данни за вход. Ключ само за този bucket е по-безопасен от главния ключ на акаунта.",
