  "dest.free": "{size} свободни",
  "dest.location": "Външно хранилище",
  "dest.route.s3": "S3 услугите ползват собствения S3 бекенд на restic, а не rclone, което позволява да се прилагат клас на съхранение и object lock.",
  "dest.route.rclone": "restic стига до тази услуга през rclone, който се доставя с BombVault. Remote-ът после се появява в rclone.conf в Настройки, Дестинации.",
  "dest.route.rest": "restic говори директно с rest-server.",
  "dest.route.path": "Папка под монтираната папка с данни на хоста.",
  "dest.lock.s3": "Включи версиониране и object lock за bucket-а. Тогава старите версии оцеляват, дори някой да изтрива с ключа. BombVault още не може да провери това за {name}.",
  "dest.lock.none": "{name} не може да откаже изтриване. Който влезе в сървъра ти, влиза и в това външно хранилище. Срещу ransomware помага rest-server или услуга за съхранение с object lock, например като втора дестинация.",
  "dest.lock.rest": "След запазване тестът за манипулация на картата на раздела проверява дали сървърът отказва изтриване.",
  "dest.recovery": "Комплектът за възстановяване изброява тази дестинация с хранилището на всеки раздел под нея. Самият вход се връща със Самобекъп на BombVault; без него се въвежда отново на новия сървър.",
  "dest.recovery.token": "{name} постоянно подновява достъпа си, затова токен от по-стар Самобекъп може да е изтекъл. Тогава влез още веднъж. Самото хранилище не е засегнато.",
  "dest.recovery.ssh": "SSH ключът също се връща със Самобекъп. При нова инсталация без него новият ключ трябва да се постави на сървъра.",
