  "offsite.prune.title": "5 · Прочистване извън обекта",
  "offsite.prune.info": "Тази стъпка само показва какво се случва, тя не настройва нищо. Дали това копие се прочиства, се решава от само-добавяне в стъпка 4 и от стойностите за пазене в Настройки, Дестинации. За да прочистиш все пак копие със само-добавяне, изпълни restic forget --prune от страната на хранилището — по свой собствен график или като вдигнеш за кратко втори REST сървър без само-добавяне, прочистиш през него и го спреш отново.",
  "offsite.prune.stateFarSide": "Оттук нищо не прочиства това копие. Само-добавяне е включено, така че BombVault само добавя към него, а прочистването е работа на другата страна.",
  "offsite.prune.statePolicy": "BombVault прочиства това копие след всяка репликация, следвайки политиката за задържане извън обекта.",
  "offsite.prune.stateNone": "Нищо не прочиства това копие. Само-добавяне е изключено и всички стойности за пазене извън обекта са 0, така че то расте, докато дискът издържа.",
  "offsite.prune.effective": "Пази {last} последни, {daily} дневни, {weekly} седмични, {monthly} месечни, {yearly} годишни.",
  "offsite.prune.editedElsewhere": "Задава се в Настройки, Дестинации. Всички източници делят тези стойности, освен ако някой има свои правила.",
  "offsite.prune.budgetInfo": "Вдига тревога, щом хранилището извън обекта надхвърли този брой гигабайти. То никога не изтрива нищо, така че е предпазната мрежа за копие, което нищо не прочиства.",
  "settings.retentionImmutableNotPruned": "Дестинация извън обекта със само-добавяне никога не се прочиства оттук, каквото и да пише в тези стойности. Нейната собствена стъпка в помощника за извън обекта обяснява как да я прочистиш от страната на хранилището.",

  // Additional off-site targets (multi-off-site)
