  "settings.dbDumpsHint": "Преди всяко архивиране разпознатите контейнери с PostgreSQL, MySQL и MariaDB се дъмпват като собствени точки за възстановяване. Оттук изключваш това за всички контейнери наведнъж, например когато базите ти вече се дъмпват сами. Отделен контейнер се изключва от неговата карта.",
