  // Retention
  "excludes.advisoryImmichDb": "Immich съхранява албумите, лицата и датите на всяка снимка в база данни PostgreSQL, която работи в отделен, собствен контейнер, така че това архивиране не я съдържа. Възстановяването оттук връща снимките, но без нищо от това. BombVault прави дъмп на контейнера с тази база данни автоматично, когато той бъде архивиран, така че провери дали е включен в графика ти.",
  "excludes.advisoryNextcloudDb": "Nextcloud съхранява акаунтите, споделянията и етикетите си в база данни, която обикновено работи в отделен контейнер, така че това архивиране не я съдържа. Файловете се връщат, споделянето не. BombVault прави дъмп на контейнера с тази база данни автоматично, когато той бъде архивиран, така че провери дали е включен в графика ти.",
