  "excludes.presetHint.trickplay": "Изображения за лентата за превъртане. Планирана задача ги създава отново след възстановяване.",
  "excludes.presetHint.metadata": "Плакати и изображения, изтеглени от приложението. Опресняването на метаданните ги изтегля отново, но тук са и изображенията, които сте качили сами, и те ще се загубят. Този запис е изключен в началото.",
