  "excludes.presetHint.encodedVideo": "Копия, прекодирани от приложението за възпроизвеждане. Оригиналите остават в архива и приложението ги прекодира отново след възстановяване.",
  "excludes.presetHint.models": "Модели за машинно обучение. Приложението ги изтегля отново при стартиране.",
  "rcloneRemote.heading": "Добави SMB или WebDAV дестинация",
  "rcloneRemote.hint": "Достига до споделяне на Windows или Samba или до WebDAV сървър като Nextcloud, без да го монтира на хоста. restic не препоръчва хранилище върху монтирано CIFS споделяне, а този начин изобщо избягва монтирането. Паролата се предава на rclone, който я съхранява в собствен формат, и никога не се пази в чист текст. NFS не се предлага тук, защото нито restic, нито rclone го поддържат: за NFS монтирай експорта на Unraid и насочи път за архивиране към него.",
