  "settings.offsiteDrillsHelp": "Възстановява целия архив извън обекта по графика на проверката, за да докаже отдалеченото възстановяване. Това изтегля наново цялото архивиране при всяко изпълнение, което струва трафик при таксувани по обем облаци (например Backblaze B2). Изключи, за да запазиш само безплатната локална проверка на целостта и да изпълняваш DR проверката извън обекта ръчно.",

  // Pre/post-backup hooks
  "hooks.hint": "Командите се изпълняват в контейнера с sh -c. Пре-командата се изпълнява преди архивирането; използвай я, за да подготвиш данни, които трябва да бъдат архивирани, например изхвърляне на кеш на диска. Разпознатите бази данни се дъмпват автоматично и не се нуждаят от кука. Ако пре-командата се провали, архивирането се прекратява. Пост-командата се изпълнява след повторното стартиране на контейнера и грешката ѝ само се записва в лог. Куките само изпълняват команди, те не добавят допълнителни папки към архивирането.",
  "hooks.pre": "Пре-команда за архивиране",
  "hooks.post": "Пост-команда за архивиране",
  "folders.title": "Архивирани папки",
