  "dbdump.saveHint": "Записва дъмпа като файл в избраната папка на сървъра, със собственик nobody:users, за да можеш да го отвориш през мрежовата споделена папка. Файлът съдържа всички таблици и хешовете на паролите на потребителите на базата; дръж го там, където само ти стигаш.",
  "dbdump.saveCancelHint": "Отказът спира записа и премахва недовършения файл.",
  "dbdump.savedTo": "Записано в {path}",
  "dbdump.import": "Импорт в нова база данни",
  "dbdump.importConfirm": "Да се импортира ли този {engine} {version} дъмп в {container}? BombVault спира контейнера, премества папката с данните настрани (тя се запазва, нищо не се трие), стартира контейнера с празна папка и импортира дъмпа. Приложенията, които ползват тази база, виждат състоянието ѝ от момента на дъмпа.",
  "dbdump.importConfirmNoVersion": "Да се импортира ли този {engine} дъмп в {container}? BombVault спира контейнера, премества папката с данните настрани (тя се запазва, нищо не се трие), стартира контейнера с празна папка и импортира дъмпа. Приложенията, които ползват тази база, виждат състоянието ѝ от момента на дъмпа.",
  "dbdump.importNoVersion": "Този дъмп не записва версията на базата данни. Импортът се проваля, ако сървърът не може да я прочете.",
  "dbdump.importStops": "one=Докато импортира, BombVault спира и {apps} и след това го стартира отново. Ако импортирането се провали, след като вече е започнало, старите данни остават настрана, а приложението спряно.|other=Докато импортира, BombVault спира и тези приложения: {apps}. След това ги стартира отново. Ако импортирането се провали, след като вече е започнало, старите данни остават настрана, а приложенията спрени.",
  "dbdump.importDone": "Базата данни е импортирана.",
  "dbdump.keptIncluded": "Копието стои до папката с данни, затова всяко резервно копие или реплика на папката или набора от данни над нея го включва. Премахни го, щом базата данни работи.",
  "dbdump.removeKept": "Премахни копието",
  "dbdump.keptRemoved": "Копието е премахнато.",
  "dbdump.importRefused.busy": "В момента тече друго архивиране или възстановяване. Опитай пак, когато приключи.",
  "dbdump.importRefused.notRunning": "Първо стартирай контейнера; импортът се нуждае от работещия сървър.",
  "dbdump.importRefused.engineMismatch": "Този дъмп идва от друг тип база данни от този, който контейнерът работи.",
  "dbdump.importRefused.noDataMount": "BombVault не достига папката с данните на този контейнер и не може да я премести безопасно настрани. Импортирай дъмпа ръчно, както описва аварийният комплект.",
  "dbdump.importRefused.version": "Сървърът работи с версия {server}, дъмпът идва от {dump}. Използвай образ с версия {dump} или по-нова за този импорт.",
  "dbdump.importRefused.versionSameMajor": "Сървърът работи с версия {server}, дъмпът идва от {dump}. MySQL и MariaDB внасят дъмп само в основната версия, от която е направен, затова използвай образ с версия {dump} за този импорт.",
  "dbdump.importRefused.damaged": "Този дъмп е повреден и не може да бъде импортиран.",
