  "relay.plaintextWarning": "Този адрес няма TLS, затова ключът за препредавателя минава през мрежата като открит текст. Всеки по пътя може да го прочете и да се присъедини към групата ти в препредавателя. Не може да прочете какво си изпращат инстанциите ти, но вижда кои инстанции си говорят и кога. Ползвай това само в мрежа, на която имаш доверие.",
