  "zfs.safety.hint": "BombVault направи тези моментни снимки точно преди възстановяване в набор от данни, за да може състоянието отпреди да се върне. BombVault никога не ги изтрива сам. Отделни файлове връщаш, като ги копираш от .zfs/snapshot/<name> вътре в набора. zfs rollback работи само докато това е най-новата моментна снимка на този набор; zfs rollback -r изтрива всяка по-нова снимка, включително автоматичните.",
