  // Restore from another BombVault repo
  "recovery.abTitle": "Импорт от плъгина Appdata.Backup",
  "recovery.abIntro": "Превръща архивите, записани от плъгина Appdata.Backup, в точки за възстановяване на съответните контейнери, всяка с датата, на която плъгинът я е създал. Архивите само се четат, никога не се променят или изтриват. Всеки се разархивира до хранилището, архивира се и разархивираното копие отново се изтрива, затова там трябва да има място за най-големия архив.",
