  "mcp.rotate": "Замени ключа",
  "mcp.rotateTitle": "Да се замени ли този ключ?",
  "mcp.rotateConfirm": "{name} получава нов ключ, а старият спира да работи веднага. Обнови всеки клиент, който го използва.",
  "mcp.rotated": "Ключът е заменен",
