  "anomaly.action.expected": "Отбележи като очаквана",
  "anomaly.acknowledgeHint": "Отбелязва аномалията като видяна и я затваря. Докато причината е налице, тя не се съобщава отново; след като причината отпадне и се върне, се съобщава. Ако тази аномалия задържа стари копия, от следващото почистване те отново ще се изтриват. Ако промяната е била нарочна, по-добре я отбележи като очаквана.",
  "anomaly.expectedHint": "Казва на BombVault, че промяната е била нарочна. Нов размер или нова продължителност стават нормалното ниво след още 10 копия, а проверката за почти празен източник остава включена. При нови данни количества до това вече не се съобщават за този запис. Ако тази аномалия задържа стари копия, от следващото почистване те отново ще се изтриват.",
