  "anomaly.sentence.newData": "{name} добави {bytes} нови данни в едно копие. Обикновено добавя най-много {typical}.",
  "anomaly.sentence.newDataRewrite": "{name} пренаписа {bytes} в едно копие, поне половината от всичко, което се архивира ({source}). Ако не си променял толкова, провери дали файловете не са криптирани или заменени.",
  "anomaly.sentence.newDataRenamed": "Всички файлове на {name} изглеждат нови, макар да съществува по-старо копие, и {bytes} от {source} са записани отново. Файлове, преименувани и пренаписани едновременно, са типични за рансъмуер. Провери файловете преди всичко друго.",
  "anomaly.sentence.newDataFull": "BombVault прочете всички файлове на {name} наново, защото нито едно по-старо копие не съвпадна (ново хранилище, нови папки или променено криптиране). Записани нови данни: {bytes}.",
