  "anomaly.settings.title": "Аномалии",
  "anomaly.settings.hint": "Сравнява всяко копие на даден запис с неговата собствена история и съобщава какво не пасва. Работи във фонов режим след всяко копие и не забавя нито едно. Повечето проверки започват след 10 копия на записа; неуспехите, презаписването на повечето данни и почти празният източник се проверяват от самото начало. Свободното място се следи за локалните хранилища и за rclone хранилищата, които го отчитат; на потребителския дял на Unraid това е свободното място на целия масив.",
