  "anomaly.settings.holdToggle": "Пази старите копия, когато източник рязко се свие или бъде презаписан",
  "anomaly.settings.holdHint": "Три находки спират изтриването на стари копия: източник, който внезапно е почти празен, такъв, който е станал много по-малък, и копие, записало отново повечето данни, както изглежда рансъмуер. Политиката за съхранение иначе би изтрила добрите по-стари копия едно по едно. Докато такава аномалия е отворена, старите копия само на този запис (или на този дъмп на база данни или ZFS набор от данни) се пазят; всичко останало се почиства както обикновено. Потвърди аномалията или я отбележи като очаквана, за да продължи изтриването.",
