  "entry.export.where": "Файловете отиват до хранилището на сървъра, а не в папката ти за изтегляния. Можеш да ги вземеш през споделена папка или по SSH.",
  "entry.export.segments": "Този архив на ВМ съдържа всеки диск като номерирани файлове със сегменти до един манифест. Подредени и слепени, те дават образа на диска.",
