  "whatsNew.way": "one=Насам към {n} промяна:|other=Насам към {n} промени:",
  "whatsNew.page.entry": "Страница на запис",
  "whatsNew.page.location": "Страница на дестинация",
  "whatsNew.overviewHead": "Зелените точки показват какво е ново. Щракване върху точка я скрива, а всичките са в Настройки, Инфо.",
  "whatsNew.overviewCustomize": "Прегледът започва с пет карти. Още чакат под „Персонализирай“, а всяка карта може да се мести, да сменя размера си и да се скрива.",
  "whatsNew.overviewDecline": "„Не архивирай“ маха запис от този списък, когато го пропускаш нарочно. Тогава той вече не се брои за незащитен.",
  "whatsNew.overviewInstances": "В приложението за Android най-горе в прегледа е името на инстанцията, на която си. Стрелката пред името те връща към прегледа на приложението, където са всички твои инстанции.",
  "whatsNew.backupsTiles": "Всичко архивирано е в един списък. Плочките избират вид.",
  "whatsNew.backupsBar": "„Филтри“, „Подреждане“ и „Търсене“ са три бутона над списъка.",
  "whatsNew.backupsRow": "Редът показва един статус, а останалото е в балончето до името. Редовете се избират като файлове: Ctrl+щракване, Shift+щракване или продължително натискане.",
  "whatsNew.backupsActions": "Основното действие на страницата се носи долу вдясно. „Още“ съдържа редките.",
  "whatsNew.entryPage": "Всеки запис има своя страница с три раздела: Архивирания, Настройки и Проверка.",
  "whatsNew.entryDefaults": "Записът следва графика и дестинацията по подразбиране, докато не получи свои тук.",
  "whatsNew.restoreTiles": "„Възстановяване“ е една страница за всичко. Избери раздел или потърси запис, после избери архив от неговата времева линия.",
  "whatsNew.restoreWhere": "Един прозорец пита какво да се върне и къде. „До оригинала“ връща копие и оставя оригинала както е.",
  "whatsNew.restoreMany": "Избери няколко записа с Ctrl+щракване, Shift+щракване или продължително натискане и ги възстанови заедно, един след друг.",
  "whatsNew.restoreEmergency": "Оттук започва помощникът при авария. Връща сървър, който го няма или е настроен отново, в четири стъпки.",
  "whatsNew.anomaliesTiles": "Плочките избират степента на важност. „Отворена“ или „Затворена“ избира списъка.",
  "whatsNew.anomaliesRings": "Пръстен за всеки запис показва доколко откриването е научило кое е нормално.",
  "whatsNew.storageList": "Локалните и външните дестинации са в един списък. Всяка дестинация има своя страница.",
  "whatsNew.storageFlow": "3-2-1 като картина. Всяка линия от раздел към дестинация е превключвател, включително Локално, и едно щракване я включва или изключва. Всеки раздел показва колко от записите му се архивират другаде.",
  "whatsNew.locationKeep": "Задържането е „Кратко“, „Балансирано“, „Дълго“ или със свои стойности. Времевата линия показва кои архиви пази едно правило.",
  "whatsNew.locationMove": "„Премести“ пренася копието на раздел към друга дестинация, с цялата му история.",
  "whatsNew.instancesPair": "Инстанциите се сдвояват с дванайсет думи. После всяка показва ролите си като плочки.",
  "whatsNew.instancesPhones": "Телефоните, сдвоени през приложението за Android, получават собствена карта до инстанциите.",
  "whatsNew.settingsTiles": "Настройките са четиринайсет плочки. Натисни / или Ctrl+K, за да търсиш във всички, дори по имената, които страниците са имали преди.",
  "whatsNew.settingsPin": "Дестинации и Инстанции са плочки в настройките. Този превключвател ги закрепва към страничната лента.",
  "whatsNew.settingsWeek": "Седмицата като лента, с всяко планирано изпълнение от понеделник до неделя.",
  "whatsNew.pairingSteps": "Три карти показват как работи сдвояването. Под тях препредавателят има четири форми, всяка със своя картинка.",
  "whatsNew.settingsVersion": "Инфо съдържа Версия, Помощ и Относно. Версия показва BombVault, GlimStone, restic и rclone. Бутонът ѝ Ново отваря списъка с промените, а щом ги видиш всичките, бележките по изданието.",
  "whatsNew.settingsManual": "Жълтият бутон под „Помощ“ отваря наръчника.",
  "whatsNew.lookGlyphs": "„Ъгли“ и „Анимация“ показват символ за всеки избор, както „Тема“.",
